import{_ as t}from"./chunks/ai-pipeline-02-pr-review.GgnxoMrq.js";import{_ as i,o as r,c as a,a0 as n}from"./chunks/framework.DScjKhBS.js";const g=JSON.parse('{"title":"PR Review Continuity Under Capacity Loss","description":"Research microsite on maintaining safe, effective pull-request review when key developers are unavailable or cannot fully understand large AI-augmented changes.","frontmatter":{"layout":"doc","title":"PR Review Continuity Under Capacity Loss","description":"Research microsite on maintaining safe, effective pull-request review when key developers are unavailable or cannot fully understand large AI-augmented changes."},"headers":[],"relativePath":"reports/pr-review-continuity/index.md","filePath":"reports/pr-review-continuity/index.md"}'),o={name:"reports/pr-review-continuity/index.md"};function s(d,e,c,l,p,u){return r(),a("div",null,[...e[0]||(e[0]=[n('<figure class="report-section-image-wrapper" aria-labelledby="fig-pr-continuity-caption"><img src="'+t+'" alt="Manuscript-style PR with margin notes and a human approval hand at the merge gate" loading="lazy" class="report-section-image"><figcaption id="fig-pr-continuity-caption">PR continuity: AI first-pass notes with a human-controlled merge gate</figcaption></figure><h1 id="pr-review-continuity-under-capacity-loss" tabindex="-1">PR Review Continuity Under Capacity Loss <a class="header-anchor" href="#pr-review-continuity-under-capacity-loss" aria-label="Permalink to &quot;PR Review Continuity Under Capacity Loss&quot;">​</a></h1><p>This microsite addresses a specific operating risk: a period where one or more developers cannot fully understand PR contents or cannot perform deep review consistently.</p><p>It synthesizes:</p><ul><li>Existing <code>dark-factory</code> project research (review bottlenecks, AI guardrails, governance controls, and outcome-based validation)</li><li>External guidance and evidence (Google Engineering Practices, GitHub PR practices, SmartBear review research, NIST SSDF, and emerging AI-assistance cognition studies)</li></ul><hr><h2 id="core-thesis" tabindex="-1">Core thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core thesis&quot;">​</a></h2><p>When reviewer comprehension drops, quality and security do not fail because of a single bad PR. They fail through an accumulation of:</p><ol><li>Oversized changes that exceed human cognitive bandwidth</li><li>Weak intent documentation (<code>what/why/risk/test</code> unclear)</li><li>Implicit trust in AI output without structured verification</li><li>Concentrated reviewer knowledge (single-point-of-failure maintainers)</li></ol><p>The fix is an operating model, not a single tool: <strong>smaller review units, explicit review contracts, deterministic checks, and mandatory human accountability at merge gates</strong>.</p><hr><h2 id="audience-and-outcomes" tabindex="-1">Audience and outcomes <a class="header-anchor" href="#audience-and-outcomes" aria-label="Permalink to &quot;Audience and outcomes&quot;">​</a></h2><ul><li><strong>Leadership outcome:</strong> Reduce delivery risk during reviewer capacity shocks without freezing delivery.</li><li><strong>Engineering outcome:</strong> Preserve review depth and merge confidence through explicit risk tiers, evidence contracts, and change-sizing rules.</li><li><strong>Shared outcome:</strong> Keep AI useful as first-pass acceleration while preventing blind-trust approvals.</li></ul><hr><h2 id="microsite-sections" tabindex="-1">Microsite sections <a class="header-anchor" href="#microsite-sections" aria-label="Permalink to &quot;Microsite sections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Focus</th></tr></thead><tbody><tr><td><a href="./reports/pr-review-continuity/01-problem-shape-and-signals.html">1. Problem shape and measurable signals</a></td><td>How to detect that review comprehension is degrading</td></tr><tr><td><a href="./reports/pr-review-continuity/02-failure-modes-and-risk-model.html">2. Failure modes and risk model</a></td><td>Where quality/security failures emerge when reviewers are overloaded</td></tr><tr><td><a href="./reports/pr-review-continuity/03-operating-model-for-constrained-review-capacity.html">3. Operating model for constrained review capacity</a></td><td>A practical process for triage, review depth, and escalation</td></tr><tr><td><a href="./reports/pr-review-continuity/04-pr-design-and-work-slicing-patterns.html">4. PR design and work slicing patterns</a></td><td>How to shape PRs so they remain reviewable</td></tr><tr><td><a href="./reports/pr-review-continuity/05-ai-assisted-review-without-blind-trust.html">5. AI-assisted review without blind trust</a></td><td>Safe AI usage patterns when human reviewer capacity is thin</td></tr><tr><td><a href="./reports/pr-review-continuity/06-30-60-90-rollout.html">6. 30-60-90 day rollout</a></td><td>Adoption plan, KPIs, and stop conditions</td></tr><tr><td><a href="./reports/pr-review-continuity/07-sources-and-evidence-map.html">7. Sources and evidence map</a></td><td>Internal and external references</td></tr></tbody></table><p>Start with <a href="./reports/pr-review-continuity/01-problem-shape-and-signals.html">Problem shape and measurable signals</a>.</p><hr><h2 id="one-line-positioning" tabindex="-1">One-line positioning <a class="header-anchor" href="#one-line-positioning" aria-label="Permalink to &quot;One-line positioning&quot;">​</a></h2><p>Treat PR review continuity as an engineering reliability problem: design the review system so it remains safe when reviewer attention is the constrained resource.</p>',20)])])}const v=i(o,[["render",s]]);export{g as __pageData,v as default};
